/* HEXA BATTLEGROUNDS setup — PART 14 OF 19. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-sequence-1', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  5, 9, 13, 17, 21, ?\nBRAVO:  2, 3, 5, 8, 13, ?\nCHARLIE:  4, 8, 16, 32, 64, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number plus 10."},"intel":{"title":"Insider tip","body":"The genuine pattern is BRAVO. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["31"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'BRAVO continues with 21; converted: 31.', null, 25, 'published'), ('mission-sequence-2', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  4, 8, 16, 32, 64, ?\nBRAVO:  5, 8, 11, 14, 17, ?\nCHARLIE:  4, 9, 19, 39, 79, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number multiplied by 2."},"intel":{"title":"Insider tip","body":"The genuine pattern is CHARLIE. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["318"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'CHARLIE continues with 159; converted: 318.', null, 25, 'published'), ('mission-sequence-3', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  4, 9, 19, 39, 79, ?\nBRAVO:  4, 9, 16, 25, 36, ?\nCHARLIE:  2, 4, 6, 10, 16, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number minus 1."},"intel":{"title":"Insider tip","body":"The genuine pattern is ALPHA. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["158"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'ALPHA continues with 159; converted: 158.', null, 25, 'published'), ('mission-sequence-4', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  4, 11, 18, 25, 32, ?\nBRAVO:  4, 8, 16, 32, 64, ?\nCHARLIE:  1, 3, 7, 15, 31, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number plus 10."},"intel":{"title":"Insider tip","body":"The genuine pattern is BRAVO. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["138"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'BRAVO continues with 128; converted: 138.', null, 25, 'published'), ('mission-memory-0', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"📱   🎧   🔋   ☕   📦   🍩   📎","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = X    🍩 = I    📎 = J    🖥️ = S    🔑 = W    📦 = F    🎧 = D    📱 = Q    🧾 = R    🔋 = M"},"intel":{"title":"Positions that matter","body":"Use only objects number 5, 6, 7 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["FIJ"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 5, 6, 7 were 📦 🍩 📎 → FIJ.', null, 25, 'published'), ('mission-memory-1', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"📎   🔑   🧾   ☕   🖥️   📦   🎧","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = F    🍩 = D    📎 = K    🖥️ = N    🔑 = P    📦 = Y    🎧 = X    📱 = J    🧾 = R    🔋 = T"},"intel":{"title":"Positions that matter","body":"Use only objects number 2, 4, 6 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["PFY"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 2, 4, 6 were 🔑 ☕ 📦 → PFY.', null, 25, 'published'), ('mission-memory-2', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"🔋   🍩   ☕   🔑   🧾   📦   📎","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = B    🍩 = O    📎 = X    🖥️ = U    🔑 = I    📦 = N    🎧 = G    📱 = H    🧾 = S    🔋 = L"},"intel":{"title":"Positions that matter","body":"Use only objects number 1, 3, 6 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["LBN"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 1, 3, 6 were 🔋 ☕ 📦 → LBN.', null, 25, 'published'), ('mission-memory-3', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"🔑   🖥️   📱   ☕   📦   🔋   📎","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = J    🍩 = Z    📎 = R    🖥️ = D    🔑 = Y    📦 = F    🎧 = G    📱 = C    🧾 = N    🔋 = T"},"intel":{"title":"Positions that matter","body":"Use only objects number 1, 3, 4 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["YCJ"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 1, 3, 4 were 🔑 📱 ☕ → YCJ.', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('relay-triad-100', 'relay', 'relay', 'Intelligence Exchange', 'tech', 1, array['social','coffee','public','market']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"Binary 1111 equals which decimal number?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Binary 11 equals which decimal number?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"HTTP status code for \"Not Found\"?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["15"]},{"label":"Part 2 (Decoder)","accept":["3"]},{"label":"Part 3 (Intel)","accept":["404"]}]'::jsonb, true, 3, 240, 'The three numbers have 2, 1, 3 digits.', 'Binary 1111 equals which decimal number? → 15 | Binary 11 equals which decimal number? → 3 | HTTP status code for "Not Found"? → 404', null, 25, 'published'), ('relay-triad-101', 'relay', 'relay', 'Intelligence Exchange', 'tech', 1, array['social','coffee','public','market']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"Binary 1111 equals which decimal number?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Hexadecimal 1A equals which decimal number?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"HTTP status code for \"Forbidden\"?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["15"]},{"label":"Part 2 (Decoder)","accept":["26"]},{"label":"Part 3 (Intel)","accept":["403"]}]'::jsonb, true, 3, 240, 'The three numbers have 2, 2, 3 digits.', 'Binary 1111 equals which decimal number? → 15 | Hexadecimal 1A equals which decimal number? → 26 | HTTP status code for "Forbidden"? → 403', null, 25, 'published'), ('relay-triad-102', 'relay', 'relay', 'Intelligence Exchange', 'tech', 1, array['social','coffee','public','market']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"HTTP status code for \"Not Found\"?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"In most programming languages, the index of the first array element is?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"Which port does plain HTTP use by default?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["404"]},{"label":"Part 2 (Decoder)","accept":["0"]},{"label":"Part 3 (Intel)","accept":["80"]}]'::jsonb, true, 3, 240, 'The three numbers have 3, 1, 2 digits.', 'HTTP status code for "Not Found"? → 404 | In most programming languages, the index of the first array element is? → 0 | Which port does plain HTTP use by default? → 80', null, 25, 'published'), ('relay-triad-103', 'relay', 'relay', 'Intelligence Exchange', 'tech', 1, array['social','coffee','public','market']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"Binary 11 equals which decimal number?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Hexadecimal FF equals which decimal number?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"How many bytes are in one kibibyte (KiB)?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["3"]},{"label":"Part 2 (Decoder)","accept":["255"]},{"label":"Part 3 (Intel)","accept":["1024"]}]'::jsonb, true, 3, 240, 'The three numbers have 1, 3, 4 digits.', 'Binary 11 equals which decimal number? → 3 | Hexadecimal FF equals which decimal number? → 255 | How many bytes are in one kibibyte (KiB)? → 1024', null, 25, 'published'), ('relay-triad-104', 'relay', 'relay', 'Intelligence Exchange', 'tech', 1, array['social','coffee','public','market']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"Binary 1000 equals which decimal number?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"How many characters does a standard SHA-256 hex digest have?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"HTTP status code for \"Not Found\"?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["8"]},{"label":"Part 2 (Decoder)","accept":["64"]},{"label":"Part 3 (Intel)","accept":["404"]}]'::jsonb, true, 3, 240, 'The three numbers have 1, 2, 3 digits.', 'Binary 1000 equals which decimal number? → 8 | How many characters does a standard SHA-256 hex digest have? → 64 | HTTP status code for "Not Found"? → 404', null, 25, 'published'), ('relay-triad-105', 'relay', 'relay', 'Intelligence Exchange', 'tech', 1, array['social','coffee','public','market']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"HTTP status code for \"Not Found\"?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Which port does plain HTTP use by default?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"How many hexadecimal digits exist (0 to F)?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["404"]},{"label":"Part 2 (Decoder)","accept":["80"]},{"label":"Part 3 (Intel)","accept":["16"]}]'::jsonb, true, 3, 240, 'The three numbers have 3, 2, 2 digits.', 'HTTP status code for "Not Found"? → 404 | Which port does plain HTTP use by default? → 80 | How many hexadecimal digits exist (0 to F)? → 16', null, 25, 'published'), ('mission-bughunt-0', 'bughunt', 'mission', 'Bug Hunt', 'tech', 1, array['stg','testing','office']::text[], 'A test failed in the STG lab. Find the buggy line and the value that fixes it.', '{"scout":{"title":"Source code","body":"1  total = 0\n2  for i in range(1, 5):\n3      total = total + i\n4  print(total)","mono":true},"decoder":{"title":"Test log","body":"Test log: the program printed 10.\nLanguage rule: range(a, b) stops BEFORE b."},"intel":{"title":"Requirement","body":"Spec: add the numbers 1 to 5 and print 15."}}'::jsonb, '[{"label":"Bug line number","accept":["2"]},{"label":"Correct value","accept":["6"]}]'::jsonb, false, 3, 200, 'Compare what the code does with what the requirement says.', 'Line 2 should be range(1, 6).', null, 25, 'published'), ('mission-bughunt-1', 'bughunt', 'mission', 'Bug Hunt', 'tech', 1, array['stg','testing','office']::text[], 'A test failed in the STG lab. Find the buggy line and the value that fixes it.', '{"scout":{"title":"Source code","body":"1  price = 200\n2  discount = 10\n3  final = price - price * discount\n4  print(final)","mono":true},"decoder":{"title":"Test log","body":"Test log: the program printed -1800.\nRule: a percentage must be divided by 100 before multiplying."},"intel":{"title":"Requirement","body":"Spec: apply a 10% discount to 200. Report the bug line and the correct printed value."}}'::jsonb, '[{"label":"Bug line number","accept":["3"]},{"label":"Correct value","accept":["180"]}]'::jsonb, false, 3, 200, 'Compare what the code does with what the requirement says.', 'Line 3 must use discount / 100, giving 180.', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
